/**
 * A tiny TypeScript tokenizer, just enough for the examples panel.
 *
 * Pulling in a full highlighter (shiki/prism) would add hundreds of kilobytes to
 * a site whose whole point is being a single inlined HTML file. The snippets are
 * generated by us, so a small, predictable grammar is all we need.
 */

export type TokenKind =
  | 'keyword'
  | 'string'
  | 'number'
  | 'literal'
  | 'function'
  | 'type'
  | 'property'
  | 'comment'
  | 'punctuation'

export interface CodeToken {
  text: string
  kind?: TokenKind
}

const KEYWORDS = new Set([
  'as',
  'async',
  'await',
  'break',
  'case',
  'catch',
  'class',
  'const',
  'continue',
  'declare',
  'default',
  'delete',
  'do',
  'else',
  'export',
  'extends',
  'finally',
  'for',
  'from',
  'function',
  'if',
  'import',
  'in',
  'instanceof',
  'let',
  'new',
  'of',
  'return',
  'switch',
  'throw',
  'try',
  'typeof',
  'var',
  'while',
  'yield',
])

const LITERALS = new Set(['true', 'false', 'null', 'undefined', 'this'])

const TYPE_NAMES = new Set([
  'any',
  'bigint',
  'boolean',
  'never',
  'number',
  'object',
  'string',
  'unknown',
  'void',
])

const TOKEN = /(\/\/[^\n]*|\/\*.*?\*\/)|('(?:\\.|[^'\\])*'|"(?:\\.|[^"\\])*"|`(?:\\.|[^`\\])*`)|\b(0x[0-9a-fA-F]+|\d[\d_]*(?:\.\d+)?n?)\b|([A-Za-z_$][\w$]*)|(\s+)|([^\w\s])/g

export function tokenizeLine(line: string): CodeToken[] {
  const tokens: CodeToken[] = []
  let index = 0
  TOKEN.lastIndex = 0

  for (let match = TOKEN.exec(line); match; match = TOKEN.exec(line)) {
    if (match.index > index) tokens.push({ text: line.slice(index, match.index) })
    index = match.index + match[0].length

    if (match[1]) {
      tokens.push({ text: match[0], kind: 'comment' })
      continue
    }
    if (match[2]) {
      tokens.push({ text: match[0], kind: 'string' })
      continue
    }
    if (match[3]) {
      tokens.push({ text: match[0], kind: 'number' })
      continue
    }
    if (match[4]) {
      tokens.push({ text: match[0], kind: classifyIdentifier(match[0], line, index - match[0].length) })
      continue
    }
    if (match[5]) {
      tokens.push({ text: match[0] })
      continue
    }
    tokens.push({ text: match[0], kind: 'punctuation' })
  }

  if (index < line.length) tokens.push({ text: line.slice(index) })
  return tokens
}

function classifyIdentifier(word: string, line: string, start: number): TokenKind | undefined {
  if (KEYWORDS.has(word)) return 'keyword'
  if (LITERALS.has(word)) return 'literal'
  if (TYPE_NAMES.has(word)) return 'type'

  const before = previousNonSpace(line, start)
  if (before === '.') return 'property'

  const after = nextNonSpace(line, start + word.length)
  if (after === '(') return 'function'

  if (/^[A-Z]/.test(word)) return 'type'
  return undefined
}

function previousNonSpace(line: string, start: number): string {
  for (let index = start - 1; index >= 0; index -= 1) {
    const char = line[index]
    if (char !== ' ' && char !== '\t') return char
  }
  return ''
}

function nextNonSpace(line: string, start: number): string {
  for (let index = start; index < line.length; index += 1) {
    const char = line[index]
    if (char !== ' ' && char !== '\t') return char
  }
  return ''
}
